sys_script_client.script:
function onLoad() {

    if (g_form.isNewRecord()) {
        if (g_form.getValue('category_aml') === 'new_enrollment')
            g_form.setValue('state', '1');
        else if (g_form.getValue('category_aml') === 'periodic_review_query')
            g_form.setValue('state', '1');

    }

	if (g_form.isNewRecord() && !g_user.hasRoleExactly('x_hsb11_mss_trus_0.ops_admin')) {
        var userSysId = g_user.userID;
        var ga = new GlideAjax('MSSTrusteesCallUtils');
        ga.addParam('sysparm_name', 'getUserTrusteeGroups');
        ga.addParam('sysparm_userSysId', userSysId);
        ga.getXMLAnswer(function(response) { //MSSTRUSTES-270
            var groupChoices = JSON.parse(response);
            g_form.clearOptions('scheme_code'); //clear all options
            groupChoices.forEach(function(choice) {
                g_form.addOption('scheme_code', choice.value, choice.label);

            });

        });
    }
    //MSSTrustes-250
}
